-- ============================================================
-- Mysterious — Supabase (Postgres) schema + seed data
-- HOW TO RUN: Supabase dashboard -> your "mysterious" project ->
--   SQL Editor -> New query -> paste this ENTIRE file -> Run.
-- Safe to run more than once (IF NOT EXISTS + ON CONFLICT DO NOTHING).
-- ============================================================

-- ---------- tables ----------

CREATE TABLE IF NOT EXISTS users(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  display_name TEXT NOT NULL,
  avatar TEXT DEFAULT '🧠',
  bio TEXT DEFAULT '',
  country TEXT DEFAULT '',
  is_admin INTEGER DEFAULT 0,
  is_banned INTEGER DEFAULT 0,
  xp INTEGER DEFAULT 0,
  level INTEGER DEFAULT 1,
  streak_count INTEGER DEFAULT 0,
  last_checkin DATE,
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sessions(
  token TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS notes(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  summary TEXT NOT NULL,
  points_json JSONB NOT NULL,
  read_count INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS note_reads(
  user_id BIGINT NOT NULL,
  note_id BIGINT NOT NULL,
  at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, note_id)
);

CREATE TABLE IF NOT EXISTS quizzes(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  note_slug TEXT,
  questions_json JSONB NOT NULL,
  play_count INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS quiz_attempts(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  quiz_id BIGINT NOT NULL,
  score INTEGER NOT NULL,
  total INTEGER NOT NULL,
  at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS checkins(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  date DATE NOT NULL,
  UNIQUE(user_id, date)
);

CREATE TABLE IF NOT EXISTS game_plays(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  game TEXT NOT NULL,
  score INTEGER NOT NULL,
  at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS rooms(
  slug TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  requires_approval INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS room_members(
  room_slug TEXT NOT NULL REFERENCES rooms(slug) ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  approved INT NOT NULL DEFAULT 0,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY(room_slug, user_id)
);

CREATE TABLE IF NOT EXISTS messages(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind TEXT NOT NULL,
  room_slug TEXT,
  from_id BIGINT NOT NULL,
  to_id BIGINT,
  body TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS blocks(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  blocker_id BIGINT NOT NULL,
  blocked_id BIGINT NOT NULL,
  UNIQUE(blocker_id, blocked_id)
);

CREATE TABLE IF NOT EXISTS reports(
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reporter_id BIGINT NOT NULL,
  reported_id BIGINT NOT NULL,
  reason TEXT NOT NULL,
  status TEXT DEFAULT 'open',
  created_at TIMESTAMPTZ DEFAULT now()
);

