-- ---------- seed: notes ----------
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('memory', 'Memory: How We Remember', 'Cognitive Psychology', 'Memory has three stores - sensory, short-term, and long-term. This note explains how information moves between them and how to remember better for exams.', $json$[{"point":"The Atkinson-Shiffrin model says information passes through three stores: sensory memory, short-term memory, and long-term memory.","example":"You hear a new phone number (sensory), repeat it in your head (short-term), and save it in your contacts (long-term)."},{"point":"Sensory memory holds a huge amount of information but only for 1 to 2 seconds.","example":"After lightning flashes, you can still see the bolt for a moment. That fading trace is sensory memory."},{"point":"Short-term (working) memory holds about 7 items (plus or minus 2) for less than 30 seconds unless you rehearse them. This is Miller's magic number 7 plus or minus 2.","example":"You forget a new classmate's name seconds after hearing it because your short-term memory was already full."},{"point":"Chunking groups small bits into bigger units, which increases short-term memory capacity.","example":"Memorizing 0334-567-8901 as three chunks (0334 / 567 / 8901) is easier than remembering 11 separate digits."},{"point":"Long-term memory is nearly unlimited and has two types: explicit memory (facts and events you can state) and implicit memory (skills you perform automatically).","example":"Remembering the capital of Pakistan is explicit memory. Riding a bicycle without thinking is implicit memory."},{"point":"Deep processing beats shallow repetition. Thinking about meaning (elaborative rehearsal) stores memory better than repeating words mindlessly (Craik and Lockhart's levels of processing).","example":"You remember a difficult word longer if you use it in your own sentence than if you read it ten times."},{"point":"Ebbinghaus's forgetting curve shows that we forget fastest right after learning, then the loss slows down.","example":"You forget most of a chapter the same night, but whatever survives the first day stays for weeks."},{"point":"Spaced practice (short study sessions over many days) beats massed practice (cramming one night). Testing yourself also strengthens memory - this is called the testing effect.","example":"Revising psychology notes for 30 minutes daily for a week works better than studying 5 hours the night before the exam."},{"point":"Interference causes forgetting. Proactive interference is when old learning blocks new learning. Retroactive interference is when new learning blocks old learning.","example":"Learning French makes it harder to recall the Spanish you learned last semester. That is retroactive interference."},{"point":"Retrieval cues help memory. Context-dependent memory means recall is easier in the same place and mood where you learned.","example":"You remember more in the exam hall if you revised at your study table in a similar quiet setting."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('learning-conditioning', 'Learning: Classical and Operant Conditioning', 'Learning', 'We learn by association (Pavlov) and by consequences (Skinner). This note explains both types of conditioning with clear everyday examples.', $json$[{"point":"Classical conditioning (Pavlov) is learning by association. A neutral stimulus (bell) paired with an unconditioned stimulus (food, which naturally causes salivation) becomes a conditioned stimulus that triggers a conditioned response.","example":"Hearing the university break bell makes your mouth water because you always eat samosas right after it."},{"point":"Extinction is when the conditioned response fades because the conditioned stimulus appears without the unconditioned stimulus. Spontaneous recovery is when the response returns after a rest.","example":"If the canteen closes and the bell no longer means food, your hunger response fades - but it returns on the first day of a new semester."},{"point":"Generalization is responding to similar stimuli. Discrimination is responding to only one specific stimulus.","example":"A child afraid of one stray dog fears all dogs (generalization). Later she learns only one aggressive dog is dangerous (discrimination)."},{"point":"Operant conditioning (Skinner) says behavior is shaped by its consequences. Reinforcement strengthens behavior. Punishment weakens it.","example":"Your teacher praises your class participation, so you participate more in the next lecture."},{"point":"Positive reinforcement adds something pleasant to increase behavior. Negative reinforcement removes something unpleasant to increase behavior. Both increase behavior.","example":"Getting extra marks for homework is positive reinforcement. The teacher stopping daily surprise quizzes after the class improves is negative reinforcement."},{"point":"Punishment is not the same as negative reinforcement. Punishment decreases behavior, while negative reinforcement increases it.","example":"Taking away phone time for coming late decreases lateness (punishment). Stopping nagging when you study increases studying (negative reinforcement)."},{"point":"Continuous reinforcement rewards every response. Partial (intermittent) reinforcement rewards only sometimes and makes behavior more resistant to extinction.","example":"Paying a delivery rider for every parcel is continuous. A lucky draw that sometimes gives a bonus is partial."},{"point":"There are four partial schedules. Fixed-ratio rewards after a set number of responses (factory piece-rate pay). Variable-ratio rewards after an unpredictable number (mobile game bonuses). Fixed-interval rewards after a set time (monthly salary). Variable-interval rewards after unpredictable time (random teacher checks). Variable-ratio produces the most persistent behavior.","example":"Students keep playing a mobile game because rewards come at unpredictable times - a variable-ratio schedule."},{"point":"Shaping means rewarding small steps toward the final behavior. These small steps are called successive approximations.","example":"Teaching your younger brother to pray regularly by first praising him for joining one prayer, then two, then all five."},{"point":"Observational learning (Bandura) is learning by watching others, shown in the Bobo doll experiment. It needs attention, retention, reproduction, and motivation.","example":"A younger sister copies her elder sister's study routine after watching her get first position in class."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('motivation-emotion', 'Motivation and Emotion', 'Motivation & Emotion', 'Motivation pushes us toward goals and emotion colors our experience. This note covers Maslow''s hierarchy, theories of emotion, and what drives behavior.', $json$[{"point":"Maslow's hierarchy of needs has five levels from bottom to top: physiological needs (food, water), safety needs (shelter, security), love and belonging (friends, family), esteem (respect), and self-actualization (reaching your potential). Lower needs must be reasonably satisfied before higher ones motivate you.","example":"A hungry student cannot focus on winning a debate until she has eaten lunch."},{"point":"Drive-reduction theory (Hull) says an unmet need creates an unpleasant drive. Behavior that reduces the drive is reinforced. The body tries to keep balance, called homeostasis.","example":"Thirst creates a drive. Drinking chai reduces it, so you drink chai whenever you feel thirsty."},{"point":"Incentive theory says external rewards and punishments pull behavior toward goals.","example":"A student studies hard because the class topper gets a gold medal at the annual function."},{"point":"Intrinsic motivation comes from inside (enjoyment, curiosity). Extrinsic motivation comes from outside (marks, money). Self-determination theory (Deci and Ryan) says autonomy, competence, and relatedness fuel lasting motivation.","example":"Reading psychology books for fun is intrinsic. Studying only to pass the exam is extrinsic."},{"point":"The overjustification effect: rewarding an already-enjoyed activity can reduce intrinsic interest in it.","example":"Paying a child for drawing - something she loved doing - can make her stop drawing just for fun."},{"point":"Three theories explain emotion. James-Lange: body changes come first (we feel afraid because we run). Cannon-Bard: body arousal and emotion happen at the same time. Schachter-Singer two-factor: arousal plus the label we give it creates the emotion.","example":"A fast heartbeat before a presentation becomes nervousness if you label it as fear, or excitement if you label it as eagerness."},{"point":"Ekman found six basic emotions recognized across cultures: happiness, sadness, anger, fear, surprise, and disgust.","example":"A smile means happiness whether you are in Lahore or London."},{"point":"The Yerkes-Dodson law says moderate arousal gives the best performance. Too little causes boredom. Too much causes anxiety.","example":"A little nervousness before exams sharpens you, but panic makes you forget the answers."},{"point":"Every emotion has three parts: physiological arousal (body changes), behavioral expression (face, posture), and conscious experience (what you feel inside).","example":"Anger brings a fast heartbeat, a frown, and the feeling of being treated unfairly."},{"point":"Motivation and emotion are linked. Emotions energize behavior and point it toward goals.","example":"Fear of failing motivates a student to study. Pride after success motivates her to aim even higher."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('personality-theories', 'Personality Theories', 'Personality', 'Freud, the humanists, and trait researchers all explain personality differently. This note compares their main ideas in simple words.', $json$[{"point":"Freud's structure of personality has three parts. The id seeks immediate pleasure (pleasure principle). The ego deals with reality (reality principle). The superego holds morals and conscience.","example":"Your id wants to eat the last samosa. Your superego says share it. Your ego decides to split it with your sister."},{"point":"Freud's psychosexual stages are: oral (0-1 year, mouth), anal (1-3 years, toilet training), phallic (3-6 years, Oedipus complex), latency (6 years to puberty, calm period), and genital (puberty onward, mature relationships). Unresolved conflict causes fixation at a stage.","example":"Freud said harsh toilet training could cause fixation at the anal stage, linked to extreme orderliness or messiness later in life."},{"point":"Defense mechanisms protect the ego from anxiety. Repression pushes painful memories away. Denial refuses to accept reality. Projection attributes your feelings to others. Displacement redirects anger to a safer target. Rationalization makes excuses. Reaction formation acts opposite to your feeling. Sublimation channels impulses into acceptable outlets. Regression means acting childish under stress.","example":"A student angry at her teacher scolds her younger brother instead. That is displacement."},{"point":"Humanistic theory (Rogers) says personality grows through the self-concept. Unconditional positive regard (accepting a person without conditions) builds healthy self-esteem. Conditions of worth create a gap between the real self and ideal self.","example":"Parents who love their child even when she fails an exam are giving unconditional positive regard."},{"point":"Maslow (humanistic) said people are motivated toward self-actualization - becoming the best version of themselves.","example":"A teacher who keeps learning new methods to help students is moving toward self-actualization."},{"point":"The Big Five traits (OCEAN) are: Openness (curious vs cautious), Conscientiousness (organized vs careless), Extraversion (outgoing vs reserved), Agreeableness (kind vs critical), and Neuroticism (anxious vs calm).","example":"A conscientious student keeps neat notes and submits assignments on time."},{"point":"Trait theories describe stable characteristics on a scale. Type theories put people into categories. Eysenck proposed three types: extraversion, neuroticism, and psychoticism.","example":"Calling someone an extrovert is a type. Rating how outgoing they are from 1 to 10 is a trait."},{"point":"Social-cognitive theory (Bandura) says personality comes from the interaction of person, behavior, and environment (reciprocal determinism). Self-efficacy is belief in your own ability. Rotter's locus of control is internal (I control my outcomes) vs external (luck controls them).","example":"A student with high self-efficacy believes she can pass statistics if she practices daily."},{"point":"Projective tests (Rorschach inkblots, TAT stories) reveal unconscious thoughts but are hard to score. Objective tests (MMPI) use clear true-false items and are more reliable.","example":"A TAT asks you to make up a story about a picture, which may reveal hidden feelings."},{"point":"Personality is relatively stable over time but can change after major life events. Culture shapes how traits are expressed.","example":"Extraversion looks different at a Pakistani family wedding than in a quiet library study group."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('stress-coping', 'Stress and Coping', 'Health Psychology', 'Stress is the body''s response to demands. This note explains the stress response, healthy coping styles, and how stress affects health.', $json$[{"point":"Stress is the body's response to demands. These demands are called stressors. They can be major events or daily hassles.","example":"Final exams, a sick parent, or a traffic jam on the way to university are all stressors."},{"point":"Cannon's fight-or-flight response: the body prepares to fight danger or run from it, with adrenaline and a fast heartbeat.","example":"Your heart pounds when a dog suddenly barks at you in the street."},{"point":"Selye's General Adaptation Syndrome has three stages: alarm (body mobilizes), resistance (body copes), and exhaustion (resources run out and illness risk rises).","example":"During exam week you first panic (alarm), then study for days (resistance), then fall sick after exams (exhaustion)."},{"point":"Eustress is positive stress that motivates and energizes. Distress is negative stress that harms health and performance.","example":"Excitement before a cricket final is eustress. Constant worry about fees is distress."},{"point":"Lazarus and Folkman's appraisal model: primary appraisal asks Is this a threat? Secondary appraisal asks Can I handle it? Coping follows these judgments.","example":"Hearing about a surprise test, you first think this is bad (primary), then decide you can revise tonight (secondary)."},{"point":"Problem-focused coping tackles the stressor directly. Emotion-focused coping manages the feelings about the stressor. Both are useful in different situations.","example":"Making a study timetable is problem-focused. Talking to a friend to calm down is emotion-focused."},{"point":"Healthy coping includes exercise, sleep, time management, social support, and relaxation. Unhealthy coping includes avoidance, alcohol, and blaming others.","example":"Going for a walk after a tough lecture helps. Skipping classes to avoid a difficult subject makes things worse."},{"point":"Chronic stress weakens the immune system (studied in psychoneuroimmunology) and raises the risk of hypertension and heart disease.","example":"Students under constant stress catch colds more easily during exam season."},{"point":"Type A personality (competitive, impatient, hostile) has higher heart-disease risk than Type B (relaxed, patient). This was found by Friedman and Rosenman.","example":"A student who gets furious in traffic and rushes everything shows Type A traits."},{"point":"Social support buffers stress. Emotional, informational, and practical help from others reduces the harm stress causes.","example":"Studying with friends and sharing notes lowers exam stress for everyone."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('abnormal-basics', 'Abnormal Psychology Basics', 'Abnormal Psychology', 'What makes behavior abnormal, the main disorder groups, and how they are treated. Written with care - this note explains, never diagnoses.', $json$[{"point":"Abnormal psychology studies patterns that cause significant distress or impair daily life. The DSM-5-TR defines disorders with specific criteria. Never diagnose yourself or others from a list.","example":"Feeling sad after a bad result is normal. Lasting hopelessness that stops you attending classes needs professional help."},{"point":"Four perspectives explain abnormal behavior: biological (brain, genes), psychodynamic (unconscious conflict), cognitive-behavioral (faulty thoughts and learning), and sociocultural (culture and social stress).","example":"Depression can be explained by low serotonin, childhood loss, negative thinking, or poverty - often a mix of these."},{"point":"Anxiety disorders include: generalized anxiety disorder (constant worry), panic disorder (sudden intense fear attacks), phobias (strong fears of specific things or social situations), and OCD (obsessions - unwanted thoughts - plus compulsions - repeated behaviors).","example":"Washing hands dozens of times daily to stop germ thoughts fits OCD patterns."},{"point":"Major depressive disorder needs 5 or more symptoms (low mood, lost interest, sleep or appetite changes, fatigue, worthlessness) for at least 2 weeks.","example":"A student who stops meeting friends, loses appetite, and cannot concentrate for weeks may be showing depressive symptoms."},{"point":"Bipolar disorder means alternating episodes of mania (high energy, little sleep, risky behavior) and depression.","example":"Someone who spends recklessly and sleeps 2 hours for days, then crashes into deep sadness, may be experiencing bipolar patterns."},{"point":"Schizophrenia involves psychosis: delusions (false strong beliefs), hallucinations (hearing voices that are not there), and disorganized speech and behavior.","example":"Believing the TV is sending you secret messages is a delusion."},{"point":"Somatic symptom patterns involve physical symptoms without a medical cause. Dissociative patterns involve memory gaps or identity disruption, often after trauma.","example":"A student developing paralysis-like symptoms before exams, with no medical cause, fits somatic patterns."},{"point":"Stigma makes people avoid treatment. Mental health problems are medical conditions, not character flaws.","example":"Mocking someone for visiting a psychologist stops others from seeking the help they need."},{"point":"Common treatments are psychotherapy (like CBT, which changes unhelpful thoughts), medication (prescribed by psychiatrists), and community support.","example":"CBT helps a socially anxious student test and change the thought everyone will laugh at me."},{"point":"Prevention and early help matter. Sleep, exercise, social connection, and talking to a counselor early all protect mental health.","example":"Visiting the university counselor after two bad weeks is early help, not weakness."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('research-methods', 'Research Methods Basics', 'Research Methods', 'How psychologists do research: variables, designs, sampling, ethics, and basic statistics. The foundation of every psychology course.', $json$[{"point":"A hypothesis is a testable prediction. An operational definition states exactly how a variable is measured.","example":"Hypothesis: chai improves concentration. Operational definition: concentration = number of correct answers on a 10-minute test."},{"point":"The independent variable (IV) is manipulated by the researcher. The dependent variable (DV) is measured for effects. Confounding variables must be controlled because they can distort results.","example":"IV = study method (group vs alone). DV = exam marks. Confound = some students also took private tuition."},{"point":"Experimental design uses random assignment to experimental and control groups. Only experiments let researchers claim cause and effect.","example":"Randomly giving half the class a new teaching method and comparing their results."},{"point":"Correlational design measures the relationship between variables with a correlation coefficient from -1 to +1. Correlation never proves causation.","example":"Screen time and poor sleep are correlated, but phones may not cause the poor sleep."},{"point":"Descriptive methods include: case study (one person in depth), naturalistic observation (watching natural behavior), and surveys (questionnaires).","example":"Observing children playing in a park without interfering is naturalistic observation."},{"point":"Sampling methods: random sampling gives everyone an equal chance (most representative), stratified sampling picks from subgroups, convenience sampling uses whoever is available (least representative).","example":"Surveying only your own classmates about a university issue is convenience sampling."},{"point":"Reliability means consistent results. Validity means measuring what you claim to measure. A good measure needs both.","example":"A weighing scale that always shows the same wrong weight is reliable but not valid."},{"point":"Research ethics (APA) require: informed consent, confidentiality, the right to withdraw anytime, no harm, and debriefing after the study.","example":"A questionnaire must first explain the study and let participants leave whenever they want."},{"point":"The placebo effect is improvement from belief, not treatment. Double-blind studies keep both participants and researchers unaware of who got the real treatment.","example":"In a medicine trial, neither the patient nor the doctor knows who got the real tablet."},{"point":"Descriptive statistics (mean, median, mode) summarize data. Inferential statistics test whether results can be generalized to a larger population.","example":"The class average of 72 is descriptive. Claiming the method works for all students needs inferential tests."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('social-psychology', 'Social Psychology', 'Social Psychology', 'How other people shape our thoughts and actions: conformity, obedience, persuasion, attraction, and group behavior.', $json$[{"point":"Conformity is changing behavior to match a group. In Asch's line experiment, about 37 percent of answers conformed to a wrong majority. Normative influence (wanting to fit in) and informational influence (believing others know better) drive it.","example":"Laughing at a joke you did not understand because everyone else is laughing."},{"point":"Obedience is following authority. In Milgram's experiment, 65 percent of participants gave the maximum shock when ordered by an authority figure. Obedience rises with legitimate authority and falls when the victim is near.","example":"A junior follows an unfair order from a senior just because sir said so."},{"point":"Persuasion follows the Elaboration Likelihood Model with two routes: central (careful logic, lasting change) and peripheral (celebrity, attractiveness, quick cues, temporary change).","example":"Buying soap because a famous cricketer advertises it is the peripheral route."},{"point":"Attraction grows through proximity (nearness), the mere exposure effect (liking what we see often), similarity, physical attractiveness, and reciprocity (liking those who like us).","example":"You become friends with the classmate who sits next to you every day."},{"point":"The bystander effect: people are less likely to help in a crowd because responsibility spreads out (diffusion of responsibility). Found by Darley and Latane.","example":"No one helps an injured person on a busy road because everyone assumes someone else will."},{"point":"Social facilitation: we perform better on easy tasks when watched. Social loafing: we work less hard in groups when our effort is hidden.","example":"You cycle faster when friends watch, but put less effort into a group assignment where no one sees your share."},{"point":"Deindividuation is losing self-awareness in a crowd, which can increase impulsive behavior. Groupthink (Janis) is when desire for harmony causes bad group decisions.","example":"A class group agrees to a bad plan because no one wants to disagree with the others."},{"point":"Attitudes have three parts: beliefs (cognitive), feelings (affective), and actions (behavioral). Cognitive dissonance (Festinger) is the discomfort when attitudes and behavior clash, so we change one of them.","example":"A smoker who knows smoking is harmful feels discomfort and may quit - or deny the risks."},{"point":"Stereotypes are beliefs about groups. Prejudice is feelings about groups. Discrimination is actions against groups. All three harm people.","example":"Assuming a woman in hijab cannot be a doctor is a stereotype. Refusing her a job is discrimination."},{"point":"Prosocial behavior means helping others. Altruism is helping without expecting reward. Empathy and a good mood both increase helping.","example":"Donating old clothes after seeing flood victims on TV."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('developmental-stages', 'Lifespan Development', 'Developmental Psychology', 'How we grow from baby to elder: Piaget''s thinking stages, Erikson''s life crises, and the power of early attachment.', $json$[{"point":"Development covers physical, cognitive, and social changes across the lifespan. Both nature (genes) and nurture (environment) shape it.","example":"Height is strongly genetic, but good nutrition helps a child reach their full height."},{"point":"Piaget's sensorimotor stage (birth to 2 years): learning through senses and movement. Object permanence develops - knowing things exist even when hidden.","example":"A baby cries when mother leaves the room but by 18 months stays calm, knowing she will return."},{"point":"Piaget's preoperational stage (2 to 7 years): symbolic play and language grow, but thinking is egocentric (cannot see others' viewpoints) and lacks conservation (understanding that amount stays the same despite shape change).","example":"A 4-year-old thinks the moon follows her car."},{"point":"Piaget's concrete operational stage (7 to 11 years): logical thought about concrete objects. Children understand conservation and can sort things into categories.","example":"A 9-year-old knows water poured into a tall glass is the same amount as before."},{"point":"Piaget's formal operational stage (11 years and up): abstract and hypothetical reasoning begins.","example":"A teenager can debate what would happen if exams were abolished, using pure logic."},{"point":"Erikson's first four stages: trust vs mistrust (infancy), autonomy vs shame and doubt (toddler), initiative vs guilt (preschool), industry vs inferiority (school age).","example":"A toddler allowed to try dressing herself builds autonomy."},{"point":"Erikson's fifth stage, identity vs role confusion (adolescence): forming a stable sense of self.","example":"A college student trying different subjects and friend groups is exploring identity."},{"point":"Erikson's last three stages: intimacy vs isolation (young adult), generativity vs stagnation (middle adult), integrity vs despair (late adult).","example":"A young adult building a close marriage seeks intimacy. An elder reviewing life with satisfaction shows integrity."},{"point":"Attachment (Bowlby) is the early emotional bond with caregivers. Ainsworth's Strange Situation found three styles: secure, avoidant, and ambivalent. Secure attachment predicts healthier later relationships.","example":"A securely attached child explores the playground but checks back with mother now and then."},{"point":"Teratogens (alcohol, drugs, infections) during pregnancy can harm development. Timing matters - sensitive periods mean some experiences shape outcomes more at certain ages.","example":"A mother's illness or alcohol use in the first trimester can affect the baby's organ development."}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO notes(slug, title, category, summary, points_json) VALUES ('biopsychology', 'Brain and Behaviour Basics', 'Biological Psychology', 'The biology behind behavior: neurons, neurotransmitters, brain parts, and how the nervous system controls everything you do.', $json$[{"point":"The neuron is the basic cell of the nervous system. Dendrites receive signals. The cell body (soma) processes them. The axon carries the signal. The myelin sheath speeds it up. Terminal buttons release chemicals into the synapse, the tiny gap between neurons.","example":"Touching a hot tawa sends a signal from your finger neurons to the brain in milliseconds."},{"point":"The action potential is the neuron's all-or-none electrical firing. Once the threshold is crossed, the neuron fires completely. The resting potential is about minus 70 millivolts.","example":"A dim light may not trigger vision neurons, but a bright one crosses the threshold and fires them fully."},{"point":"Neurotransmitters carry messages across synapses: serotonin (mood, sleep), dopamine (reward, movement), norepinephrine (alertness), GABA (calming, inhibitory), glutamate (excitatory, memory), acetylcholine (muscle movement, memory). Imbalances are linked to disorders.","example":"Low serotonin is linked to depression. Extra dopamine activity is linked to schizophrenia."},{"point":"The brainstem controls vital functions (breathing, heartbeat). The cerebellum coordinates movement and balance. The cerebrum handles higher thinking.","example":"Damage to the cerebellum makes walking unsteady, like when extreme tiredness affects your coordination."},{"point":"The limbic system handles emotion and memory: the amygdala processes fear, the hippocampus forms new memories, and the hypothalamus controls hunger, thirst, and temperature.","example":"The amygdala makes your heart race during a horror movie."},{"point":"The cerebrum has four lobes: frontal (planning, decisions, personality), parietal (touch and body senses), temporal (hearing, language, memory), and occipital (vision).","example":"The occipital lobe lets you recognize your friend's face in a crowded bazaar."},{"point":"The left hemisphere usually handles language and logic. The right handles spatial and creative tasks. The corpus callosum connects them. Split-brain research (Sperry and Gazzaniga) showed each side can work on its own.","example":"Solving math uses the left side more. Picturing a cricket field layout uses the right side more."},{"point":"The central nervous system is the brain plus spinal cord. The peripheral nervous system is the nerves to the body. Its autonomic branch splits into sympathetic (arouses: fight-or-flight) and parasympathetic (calms: rest-and-digest).","example":"The sympathetic system speeds your heart before a viva. The parasympathetic system slows it down after you relax with chai."},{"point":"The endocrine system sends hormones through the blood. The pituitary is the master gland. The adrenal glands release adrenaline during stress.","example":"Adrenal glands flood your body with adrenaline when you narrowly avoid a road accident."},{"point":"Brain plasticity means the brain can reorganize after injury, especially in childhood. New experiences build new neural connections throughout life.","example":"After a stroke, other brain areas can slowly take over lost functions with therapy."}]$json$)
ON CONFLICT (slug) DO NOTHING;

