INSERT INTO quizzes(slug, title, note_slug, questions_json) VALUES ('memory-quiz', 'Memory Quiz', 'memory', $json$[{"answer":3,"explanation":"Repeating keeps information active in short-term memory, which lasts under 30 seconds without rehearsal.","options":["Sensory memory","Long-term memory","Implicit memory","Short-term memory"],"q":"A student repeats a phone number in her head while searching for a pen. Which memory store is she using?"},{"answer":0,"explanation":"Ebbinghaus's curve shows memory drops sharply immediately after learning, then levels off.","options":["Right after learning","After one month","After one year","Forgetting happens at a constant rate"],"q":"According to Ebbinghaus's forgetting curve, when is forgetting fastest?"},{"answer":2,"explanation":"New learning (French) blocking old learning (Spanish) is retroactive interference.","options":["Proactive interference","Repression","Retroactive interference","Trace decay"],"q":"Ali learned French last year and now cannot recall the Spanish he knew before. This is an example of:"},{"answer":1,"explanation":"Spaced practice plus the testing effect strengthens long-term memory far better than cramming.","options":["Reading the chapter once","Spaced practice with self-testing","Highlighting in one color","Studying only the night before"],"q":"Which strategy best improves long-term retention?"},{"answer":3,"explanation":"Skills performed automatically are procedural (implicit) memory.","options":["Episodic memory","Semantic memory","Sensory memory","Procedural (implicit) memory"],"q":"Riding a bicycle years later without thinking uses which memory type?"},{"answer":0,"explanation":"Chunking groups items into bigger units so about 7 chunks fit in short-term memory.","options":["Increasing short-term memory capacity","Erasing old memories","Blocking interference","Speeding up forgetting"],"q":"Chunking helps memory mainly by:"},{"answer":2,"explanation":"Context-dependent memory means recall improves when the environment matches the learning environment.","options":["State-dependent memory","Eidetic memory","Context-dependent memory","Flashbulb memory"],"q":"You remember a word better in the same classroom where you learned it. This is:"},{"answer":1,"explanation":"Thinking about meaning (deep processing) creates stronger memory traces than shallow repetition.","options":["Repeating words faster","Connecting new information to meaning","Using only visual images","Shortening study time"],"q":"Elaborative rehearsal improves memory because it involves:"},{"answer":3,"explanation":"The hippocampus is essential for forming new explicit long-term memories.","options":["Loss of only old childhood memories","Total blindness","Loss of motor skills","Inability to form new long-term memories"],"q":"Damage to the hippocampus most likely causes:"},{"answer":0,"explanation":"Maintenance rehearsal is mindless repetition, which keeps information in short-term memory but builds weak long-term traces.","options":["Simple repetition without meaning","Creating permanent memories","Using visual imagery","Requiring sleep"],"q":"Maintenance rehearsal differs from elaborative rehearsal in that it involves:"}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO quizzes(slug, title, note_slug, questions_json) VALUES ('conditioning-quiz', 'Conditioning Quiz', 'learning-conditioning', $json$[{"answer":2,"explanation":"After pairing with food, the neutral bell became the conditioned stimulus that triggers salivation.","options":["Unconditioned stimulus","Unconditioned response","Conditioned stimulus","Reinforcer"],"q":"In Pavlov's experiment, after training the bell became the:"},{"answer":3,"explanation":"Responding to similar stimuli is generalization.","options":["Discrimination","Extinction","Shaping","Generalization"],"q":"A dog salivates to the sound of any bell, not just the trained one. This is:"},{"answer":0,"explanation":"Removing an unpleasant stimulus (quizzes) to increase good behavior is negative reinforcement.","options":["Negative reinforcement","Positive reinforcement","Positive punishment","Negative punishment"],"q":"The teacher stops giving surprise quizzes after the class behaves well. This is:"},{"answer":2,"explanation":"Removing something pleasant to decrease behavior is negative punishment.","options":["Positive punishment","Negative reinforcement","Negative punishment","Extinction"],"q":"Taking away a teenager's phone for breaking curfew is:"},{"answer":3,"explanation":"Rewards after an unpredictable number of responses define a variable-ratio schedule, which is most resistant to extinction.","options":["Fixed-ratio","Fixed-interval","Continuous","Variable-ratio"],"q":"A slot machine pays out after an unpredictable number of plays. This schedule is:"},{"answer":0,"explanation":"Payment after a fixed amount of time is a fixed-interval schedule.","options":["Fixed-interval","Variable-interval","Fixed-ratio","Variable-ratio"],"q":"A worker paid every Friday regardless of output is on which schedule?"},{"answer":1,"explanation":"Shaping rewards small steps that get closer and closer to the target behavior.","options":["Punishing every mistake","Reinforcing successive approximations","Pairing two stimuli","Waiting for insight"],"q":"Shaping works by:"},{"answer":3,"explanation":"Without reinforcement, the learned behavior gradually fades away.","options":["A new stimulus is added","Punishment is increased","Two behaviors merge","A behavior is no longer reinforced"],"q":"Extinction in operant conditioning occurs when:"},{"answer":2,"explanation":"Children imitated the aggression they watched, showing learning by observation.","options":["Classical conditioning","Latent learning","Observational learning","Insight learning"],"q":"Bandura's Bobo doll experiment demonstrated:"},{"answer":0,"explanation":"The rats formed a mental map without reinforcement and revealed it later - latent learning.","options":["Latent learning","Shaping","Generalization","Discrimination"],"q":"Tolman's rats learned a maze without rewards and showed their knowledge only later. This is:"}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO quizzes(slug, title, note_slug, questions_json) VALUES ('personality-quiz', 'Personality Quiz', 'personality-theories', $json$[{"answer":3,"explanation":"The ego mediates between the id's desires and reality using the reality principle.","options":["Id","Superego","Libido","Ego"],"q":"In Freud's theory, the part of personality that follows the reality principle is the:"},{"answer":0,"explanation":"Creating logical excuses for failure is rationalization.","options":["Rationalization","Projection","Sublimation","Regression"],"q":"A student fails an exam and insists the paper was unfair rather than accepting poor preparation. This defense mechanism is:"},{"answer":2,"explanation":"The Big Five (OCEAN) are Openness, Conscientiousness, Extraversion, Agreeableness, and Neuroticism. Introversion is the low end of extraversion, not a separate trait.","options":["Openness","Conscientiousness","Introversion","Neuroticism"],"q":"Which of the following is NOT one of the Big Five traits?"},{"answer":3,"explanation":"Unconditional positive regard - acceptance without conditions - builds a healthy self-concept.","options":["Strict conditions of worth","Harsh punishment","Complete independence","Unconditional positive regard"],"q":"Rogers believed healthy personality growth requires:"},{"answer":1,"explanation":"Rotter's locus of control is internal (self-controlled outcomes) versus external (luck or fate controls them).","options":["Your ability to control others","How much you believe you control your own outcomes","The brain's control of muscles","Social popularity"],"q":"Locus of control refers to:"},{"answer":0,"explanation":"Self-efficacy is confidence in your capacity to perform a task, which predicts effort and persistence.","options":["Belief in your own ability to succeed","Selfishness","Awareness of your flaws","Avoiding challenges"],"q":"Self-efficacy, a key idea in Bandura's theory, means:"},{"answer":2,"explanation":"Ambiguous inkblots let people project their unconscious thoughts and feelings into their responses.","options":["It projects images on a wall","It predicts the future","People project their thoughts onto ambiguous stimuli","It uses a projector"],"q":"The Rorschach inkblot test is called projective because:"},{"answer":3,"explanation":"Freud linked harsh or lenient toilet training to anal-retentive (overly orderly) or anal-expulsive (messy) traits.","options":["Smoking habits","Fear of strangers","Love of music","Extreme orderliness or messiness"],"q":"Fixation at Freud's anal stage is linked to:"}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO quizzes(slug, title, note_slug, questions_json) VALUES ('research-methods-quiz', 'Research Methods Quiz', 'research-methods', $json$[{"answer":3,"explanation":"The independent variable is manipulated to observe its effect on the dependent variable.","options":["Dependent variable","Confounding variable","Control variable","Independent variable"],"q":"The variable a researcher deliberately changes is the:"},{"answer":0,"explanation":"Correlations near -1 or +1 are strong. The negative sign means as one variable rises, the other falls.","options":["A strong negative relationship","No relationship","A weak positive relationship","Proof of causation"],"q":"A correlation of -0.85 means:"},{"answer":2,"explanation":"Random assignment and manipulation of the IV allow cause-and-effect conclusions.","options":["Describe behavior","Measure correlations","Show cause and effect","Survey opinions"],"q":"Only an experimental design can:"},{"answer":3,"explanation":"Observing behavior in its natural setting without interference is naturalistic observation.","options":["A case study","An experiment","A survey","Naturalistic observation"],"q":"A researcher watches children in a playground without interfering. This is:"},{"answer":0,"explanation":"Using easily available participants is convenience sampling, which limits generalizability.","options":["Convenience sampling","Random sampling","Stratified sampling","Systematic sampling"],"q":"Asking only your own classmates to fill a survey is:"},{"answer":2,"explanation":"After participation, researchers must explain the study's true purpose, especially if any deception was used.","options":["Paying participants","Deleting the data","Explaining the study's true purpose afterward","Hiring research assistants"],"q":"Debriefing means:"},{"answer":1,"explanation":"Consistency is reliability. Measuring the right thing is validity. This test has the first but not the second.","options":["Valid but not reliable","Reliable but not valid","Neither reliable nor valid","Both reliable and valid"],"q":"A test gives the same score every time but measures the wrong thing. It is:"},{"answer":3,"explanation":"Double-blind means both sides are unaware of group assignment, preventing bias and expectation effects.","options":["Participants are blindfolded","Only the researcher knows","Results are hidden from everyone","Neither participants nor researchers know who got the treatment"],"q":"In a double-blind study:"}]$json$)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO quizzes(slug, title, note_slug, questions_json) VALUES ('stress-quiz', 'Stress Quiz', 'stress-coping', $json$[{"answer":0,"explanation":"The body first alarms (mobilizes), then resists (copes), then exhausts its resources.","options":["Alarm, resistance, exhaustion","Resistance, alarm, exhaustion","Exhaustion, alarm, resistance","Alarm, exhaustion, resistance"],"q":"Selye's three stages of the General Adaptation Syndrome in order are:"},{"answer":2,"explanation":"Primary appraisal judges whether the situation is a threat. Secondary appraisal judges coping ability.","options":["Can I handle this?","Who caused this?","Is this a threat to me?","How do others cope?"],"q":"Primary appraisal in Lazarus's model asks:"},{"answer":3,"explanation":"Directly tackling the stressor is problem-focused coping.","options":["Emotion-focused coping","Avoidant coping","Denial","Problem-focused coping"],"q":"Making a study timetable to handle exam pressure is:"},{"answer":1,"explanation":"Eustress is positive, motivating stress - like healthy excitement before a match.","options":["Constant worry about fees","Excitement before a cricket final","Grief after a loss","Chronic work overload"],"q":"Which is an example of eustress?"},{"answer":0,"explanation":"The sympathetic branch arouses the body - faster heartbeat and adrenaline - for fight or flight.","options":["Sympathetic nervous system","Parasympathetic nervous system","Somatic nervous system","Endocrine system only"],"q":"The fight-or-flight response is triggered mainly by the:"},{"answer":2,"explanation":"Prolonged stress hormones weaken immune function, raising illness risk.","options":["Improves immunity","Lowers blood pressure","Suppresses the immune system","Increases appetite only"],"q":"Chronic stress harms health mainly because it:"},{"answer":3,"explanation":"Friedman and Rosenman linked the competitive, hurried, hostile Type A pattern to higher heart-disease risk.","options":["Relaxation and patience","Shyness and withdrawal","Low ambition","Competitiveness, impatience, and hostility"],"q":"A Type A personality is characterized by:"},{"answer":1,"explanation":"Managing the emotional response rather than the stressor itself is emotion-focused coping.","options":["Problem-focused coping","Emotion-focused coping","Repression","Rationalization"],"q":"Talking to a close friend to calm down after an argument is:"}]$json$)
ON CONFLICT (slug) DO NOTHING;

